use std::ffi::OsStr;
use std::os::unix::ffi::OsStrExt;
use std::process::Command;

const BIN: &str = "/workspace/dataset/test12_executable";

fn to_lower(s: &[u8]) -> Vec<u8> {
    s.iter()
        .map(|&b| if b.is_ascii_uppercase() { b + 32 } else { b })
        .collect()
}

/// Derived model: predict full stdout byte-for-byte.
fn model(d: &[u8]) -> Vec<u8> {
    let mut o: Vec<u8> = Vec::new();
    let low = to_lower(d);
    // r1 = to_ascii(d) = "xn--" ++ to_lower(d)
    o.extend_from_slice(b"xn--");
    o.extend_from_slice(&low);
    o.push(b'\n');
    // r2 = to_unicode(r1): r1 always starts with "xn--" -> strip once
    o.extend_from_slice(&low);
    o.push(b'\n');
    // r3 = punycode_encode(d) = "xn--" ++ d  (no lowercase)
    o.extend_from_slice(b"xn--");
    o.extend_from_slice(d);
    o.push(b'\n');
    // r4 = punycode_decode(r3) = d
    o.extend_from_slice(d);
    o.push(b'\n');
    // r5 = is_valid_domain(d)
    o.extend_from_slice(if !d.is_empty() && d.len() <= 255 { b"1" } else { b"0" });
    o.push(b'\n');
    // r6 = is_valid_label("testlabel")
    o.extend_from_slice(b"1\n");
    // r7 = is_ascii_domain(d)
    let ascii = d.iter().all(|&b| b < 0x80);
    o.extend_from_slice(if ascii { b"1" } else { b"0" });
    o.push(b'\n');
    // r8 = is_idn_domain(d) = any byte >= 0x80
    let idn = d.iter().any(|&b| b >= 0x80);
    o.extend_from_slice(if idn { b"1" } else { b"0" });
    o.push(b'\n');
    // r9 = to_lower("MIXEDCase")
    o.extend_from_slice(b"mixedcase\n");
    // r10 = normalize(d) = to_lower(d)
    o.extend_from_slice(&low);
    o.push(b'\n');
    // r11 = extract_tld(d)
    let tld: &[u8] = match d.iter().rposition(|&b| b == b'.') {
        Some(i) => &d[i + 1..],
        None => d,
    };
    o.extend_from_slice(tld);
    o.push(b'\n');
    // r12 = count_labels(d)
    let n = d.iter().filter(|&&b| b == b'.').count() + 1;
    o.extend_from_slice(n.to_string().as_bytes());
    o.push(b'\n');
    o
}

fn hexdump(b: &[u8]) -> String {
    let mut s = String::new();
    for &c in b {
        if c.is_ascii_graphic() || c == b' ' {
            s.push(c as char);
        } else {
            s.push_str(&format!("\\x{:02x}", c));
        }
    }
    s
}

fn run(d: &[u8]) -> Vec<u8> {
    let out = Command::new(BIN)
        .arg(OsStr::from_bytes(d))
        .output()
        .expect("spawn failed");
    out.stdout
}

fn split_lines(b: &[u8]) -> Vec<Vec<u8>> {
    let mut v: Vec<Vec<u8>> = Vec::new();
    let mut cur: Vec<u8> = Vec::new();
    for &c in b {
        if c == b'\n' {
            v.push(std::mem::take(&mut cur));
        } else {
            cur.push(c);
        }
    }
    if !cur.is_empty() {
        v.push(cur);
    }
    v
}

fn main() {
    let mut probes: Vec<(String, Vec<u8>)> = Vec::new();

    // ---- helpers -------------------------------------------------------
    let push = |probes: &mut Vec<(String, Vec<u8>)>, name: &str, v: Vec<u8>| {
        probes.push((name.to_string(), v));
    };

    // (A) pairwise sweep over interesting bytes, in the middle of ASCII text
    let interesting: Vec<u8> = vec![
        0x01, 0x07, 0x09, 0x0a, 0x0d, 0x1b, 0x20, 0x2d, 0x2e, 0x2f, 0x30, 0x40, 0x41, 0x5a,
        0x5b, 0x60, 0x61, 0x7a, 0x7b, 0x7f, 0x80, 0x81, 0xbf, 0xc0, 0xc1, 0xc2, 0xdf, 0xe0,
        0xed, 0xef, 0xf0, 0xf4, 0xf5, 0xfe, 0xff,
    ];
    for &x in &interesting {
        for &y in &interesting {
            // pattern: "A" x y "Z.CoM"
            let mut v = vec![b'A', x, y, b'Z', b'.', b'C', b'o', b'M'];
            v.push(b'D');
            push(
                &mut probes,
                &format!("pair-{:02x}{:02x}", x, y),
                std::mem::take(&mut v),
            );
        }
    }

    // (B) lead byte immediately followed by ASCII capitals (does to_lower skip?)
    for lead in [
        0x80u8, 0x9f, 0xa0, 0xbf, 0xc0, 0xc1, 0xc2, 0xc3, 0xc4, 0xd0, 0xdf, 0xe0, 0xe1, 0xe2,
        0xe3, 0xed, 0xef, 0xf0, 0xf1, 0xf4, 0xf5, 0xf8, 0xfc, 0xfe, 0xff,
    ] {
        let mut v = vec![lead];
        v.extend_from_slice(b"ABCDEFGHIJKLMNOPQRSTUVWXYZ");
        push(&mut probes, &format!("lead{:02x}+AZ", lead), v);
        let mut v2 = Vec::new();
        v2.extend_from_slice(b"ABC");
        v2.push(lead);
        v2.extend_from_slice(b"DEF");
        v2.push(lead);
        v2.extend_from_slice(b"GHI");
        push(&mut probes, &format!("AZ+lead{:02x}+interleave", lead), v2);
    }

    // (C) Turkish dotted/dotless I and friends
    push(&mut probes, "turkish-I-dot", "İSTANBUL".as_bytes().to_vec());
    push(&mut probes, "turkish-dotless", "IĞDIR".as_bytes().to_vec());
    push(&mut probes, "turkish-lower-dotless", "ıstanbul".as_bytes().to_vec());
    push(&mut probes, "turkish-mixed", "TİTLE.İTÜ.TR".as_bytes().to_vec());
    push(&mut probes, "U0130-alone-x2", "\u{0130}\u{0130}".as_bytes().to_vec());
    push(&mut probes, "U0131-alone-x2", "\u{0131}\u{0131}".as_bytes().to_vec());

    // (D) full-width Latin capitals
    push(&mut probes, "fullwidth-ABC", "ＡＢＣ".as_bytes().to_vec());
    push(&mut probes, "fullwidth-domain", "ＥＸＡＭＰＬＥ．ＣＯＭ".as_bytes().to_vec());
    push(&mut probes, "fullwidth-AZ", "ＡＺａｚ".as_bytes().to_vec());
    push(&mut probes, "fullwidth-dot-only", "\u{FF0E}".as_bytes().to_vec());
    push(&mut probes, "fullwidth-dot-mixed", "a\u{FF0E}b.c".as_bytes().to_vec());

    // (E) Cyrillic / Greek capitals
    push(&mut probes, "cyrillic-PRIMER", "ПРИМЕР.РФ".as_bytes().to_vec());
    push(&mut probes, "cyrillic-caps-all", "АБВГДЕЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ".as_bytes().to_vec());
    push(&mut probes, "greek-SIGMA", "ΣΙΓΜΑΣ".as_bytes().to_vec());
    push(&mut probes, "greek-final-sigma", "ΟΔΟΣ.ΕΛ".as_bytes().to_vec());
    push(&mut probes, "latin1-caps", "ÀÁÂÃÄÅÆÇÈÉÊËÌÍÎÏÑÒÓÔÕÖØÙÚÛÜÝÞ".as_bytes().to_vec());
    push(&mut probes, "sharp-s", "STRASSE.ß.STRAßE".as_bytes().to_vec());
    push(&mut probes, "armenian-caps", "ԱԲԳԴ".as_bytes().to_vec());
    push(&mut probes, "deseret-caps", "\u{10400}\u{10401}".as_bytes().to_vec());
    push(&mut probes, "cherokee", "ᏣᎳᎩ".as_bytes().to_vec());

    // (F) mathematical bold capitals & astral planes
    push(&mut probes, "math-bold-ABC", "\u{1D400}\u{1D401}\u{1D402}".as_bytes().to_vec());
    push(&mut probes, "math-bold-domain", "\u{1D400}\u{1D401}.\u{1D42C}".as_bytes().to_vec());
    push(&mut probes, "emoji", "\u{1F600}\u{1F1FA}\u{1F1F8}".as_bytes().to_vec());
    push(&mut probes, "plane16", "\u{10FFFD}\u{10FFFD}".as_bytes().to_vec());

    // (G) overlong UTF-8 sequences
    push(&mut probes, "overlong-nul-c080", vec![0xc0, 0x80]);
    push(&mut probes, "overlong-A-c181", vec![0xc1, 0x81]);
    push(&mut probes, "overlong-slash-c0af", vec![0xc0, 0xaf]);
    push(&mut probes, "overlong-dot-c0ae", vec![0xc0, 0xae]);
    push(&mut probes, "overlong-dot-e080ae", vec![0xe0, 0x80, 0xae]);
    push(&mut probes, "overlong-dot-f08080ae", vec![0xf0, 0x80, 0x80, 0xae]);
    push(&mut probes, "overlong-dot-in-domain", {
        let mut v = b"a".to_vec();
        v.extend_from_slice(&[0xc0, 0xae]);
        v.extend_from_slice(b"COM");
        v
    });
    push(&mut probes, "overlong-e08080", vec![0xe0, 0x80, 0x80]);
    push(&mut probes, "overlong-f0808080", vec![0xf0, 0x80, 0x80, 0x80]);
    push(&mut probes, "overlong-fc8080808080", vec![0xfc, 0x80, 0x80, 0x80, 0x80, 0x80]);
    push(&mut probes, "overlong-caps-c1", vec![0xc1, 0x81, b'A', 0xc1, 0x9a, b'Z']);

    // (H) CESU-8 / lone surrogates
    push(&mut probes, "surrogate-D800", vec![0xed, 0xa0, 0x80]);
    push(&mut probes, "surrogate-DC00", vec![0xed, 0xb0, 0x80]);
    push(&mut probes, "surrogate-DFFF", vec![0xed, 0xbf, 0xbf]);
    push(&mut probes, "cesu8-1F600", vec![0xed, 0xa0, 0xbd, 0xed, 0xb8, 0x80]);
    push(&mut probes, "cesu8-pair-with-caps", {
        let mut v = vec![0xed, 0xa0, 0xbd, 0xed, 0xb8, 0x80];
        v.extend_from_slice(b".COM");
        v
    });
    push(&mut probes, "surrogate-and-dot", vec![0xed, 0xa0, 0x80, b'.', 0xed, 0xb0, 0x80]);

    // (I) truncated / invalid UTF-8
    push(&mut probes, "trunc-c3", vec![0xc3]);
    push(&mut probes, "trunc-e2-82", vec![0xe2, 0x82]);
    push(&mut probes, "trunc-f0-9f-98", vec![0xf0, 0x9f, 0x98]);
    push(&mut probes, "bare-continuations", vec![0x80, 0x81, 0xbf, 0xbf, 0x80]);
    push(&mut probes, "fe-ff", vec![0xfe, 0xff]);
    push(&mut probes, "ff-fe", vec![0xff, 0xfe]);
    push(&mut probes, "f5-ff-sweep", vec![0xf5, 0xf6, 0xf7, 0xf8, 0xf9, 0xfa, 0xfb, 0xfc, 0xfd, 0xfe, 0xff]);
    push(&mut probes, "bom-prefix", {
        let mut v = vec![0xef, 0xbb, 0xbf];
        v.extend_from_slice(b"EXAMPLE.COM");
        v
    });
    push(&mut probes, "bom-utf16le", vec![0xff, 0xfe, b'A', 0x00_u8.wrapping_add(1), b'B']);
    push(&mut probes, "utf16be-like", vec![0x00_u8.wrapping_add(1), b'A', 0x01, b'B']);

    // (J) UTS-46 mappable things that the model claims are untouched
    push(&mut probes, "soft-hyphen", "A\u{00AD}B.COM".as_bytes().to_vec());
    push(&mut probes, "zwnj", "A\u{200C}B".as_bytes().to_vec());
    push(&mut probes, "zwj", "A\u{200D}B".as_bytes().to_vec());
    push(&mut probes, "ideographic-fullstop", "例\u{3002}中".as_bytes().to_vec());
    push(&mut probes, "one-dot-leader", "a\u{2024}b".as_bytes().to_vec());
    push(&mut probes, "halfwidth-ideographic-stop", "a\u{FF61}b".as_bytes().to_vec());
    push(&mut probes, "ideographic-space", "A\u{3000}B".as_bytes().to_vec());
    push(&mut probes, "nbsp", "A\u{00A0}B".as_bytes().to_vec());
    push(&mut probes, "ligature-ff", "\u{FB00}I\u{FB01}".as_bytes().to_vec());
    push(&mut probes, "roman-numeral", "\u{2160}\u{2161}".as_bytes().to_vec());
    push(&mut probes, "circled-A", "\u{24B6}\u{24B7}".as_bytes().to_vec());
    push(&mut probes, "kelvin-sign", "\u{212A}\u{212B}".as_bytes().to_vec());
    push(&mut probes, "combining-acute", "e\u{0301}E\u{0301}".as_bytes().to_vec());
    push(&mut probes, "nfc-vs-nfd", "É.é".as_bytes().to_vec());
    push(&mut probes, "rtl-arabic", "مثال.إختبار".as_bytes().to_vec());
    push(&mut probes, "bidi-override", "A\u{202E}B\u{202C}C".as_bytes().to_vec());

    // (K) DEL / controls in multi-byte combos
    push(&mut probes, "del-x3", vec![0x7f, 0x7f, 0x7f]);
    push(&mut probes, "del-caps", vec![0x7f, b'A', 0x7f, b'Z', 0x7f]);
    push(&mut probes, "controls-all", (0x01u8..0x21).collect::<Vec<u8>>());
    push(&mut probes, "controls-with-caps", {
        let mut v = Vec::new();
        for c in 0x01u8..0x21 {
            v.push(c);
            v.push(b'A' + (c % 26));
        }
        v
    });
    push(&mut probes, "esc-seq", vec![0x1b, b'[', b'3', b'1', b'm', b'R', b'E', b'D', 0x1b, b'[', b'0', b'm']);
    push(&mut probes, "cr-lf", vec![b'A', 0x0d, 0x0a, b'B', 0x0d, 0x0a]);
    push(&mut probes, "vertical-tab-ff", vec![0x0b, 0x0c, b'A', 0x0b, 0x0c]);

    // (L) high-byte + dot interplay for extract_tld / count_labels
    push(&mut probes, "highbyte-dot-tld", {
        let mut v = b"A".to_vec();
        v.extend_from_slice(&[0xc3, 0x89]);
        v.push(b'.');
        v.extend_from_slice(&[0xd0, 0x9f, 0xd0, 0xa0]);
        v
    });
    push(&mut probes, "dot-after-lead", vec![0xc3, b'.', 0xc3, b'.', 0xc3]);
    push(&mut probes, "continuation-2e-like", vec![0xe0, 0xae, 0xae, b'.', 0xae]);
    push(&mut probes, "trailing-dot-idn", "МОСКВА.РФ.".as_bytes().to_vec());
    push(&mut probes, "leading-dot-idn", ".РФ".as_bytes().to_vec());
    push(&mut probes, "only-dots-5", b".....".to_vec());
    push(&mut probes, "dots-and-highbytes", {
        let mut v = Vec::new();
        for i in 0..8 {
            v.push(0x80 + i);
            v.push(b'.');
        }
        v
    });

    // (M) xn-- interplay (is_idn should NOT depend on prefix)
    push(&mut probes, "xn--ascii", b"xn--abc".to_vec());
    push(&mut probes, "XN--CAPS", b"XN--ABC".to_vec());
    push(&mut probes, "xn--caf-dma", b"xn--caf-dma.com".to_vec());
    push(&mut probes, "xn--highbyte", {
        let mut v = b"xn--".to_vec();
        v.extend_from_slice("café".as_bytes());
        v
    });
    push(&mut probes, "xn--xn--", b"xn--xn--abc".to_vec());
    push(&mut probes, "xn--upper-body", b"xn--MNCHEN-3YA".to_vec());
    push(&mut probes, "Xn--mixed", b"Xn--Test".to_vec());
    push(&mut probes, "xN--mixed", b"xN--Test".to_vec());
    push(&mut probes, "xn-", b"xn-".to_vec());
    push(&mut probes, "xn---", b"xn---".to_vec());
    push(&mut probes, "xn--only", b"xn--".to_vec());

    // (N) length boundaries with multibyte, and normalize length invariance
    for n in [1usize, 2, 84, 85, 127, 128, 254, 255, 256, 257, 300, 1000] {
        let mut v = Vec::new();
        while v.len() + 2 <= n {
            v.extend_from_slice(&[0xc3, 0x89]); // É
        }
        while v.len() < n {
            v.push(b'A');
        }
        push(&mut probes, &format!("len{}-Eacute", n), v);
    }
    for n in [253usize, 254, 255, 256] {
        let mut v = Vec::new();
        while v.len() + 3 <= n {
            v.extend_from_slice(&[0xe4, 0xb8, 0xad]); // 中
        }
        while v.len() < n {
            v.push(b'Z');
        }
        push(&mut probes, &format!("len{}-cjk", n), v);
    }
    for n in [255usize, 256] {
        let mut v = Vec::new();
        while v.len() + 4 <= n {
            v.extend_from_slice(&[0xf0, 0x9f, 0x98, 0x80]);
        }
        while v.len() < n {
            v.push(b'Q');
        }
        push(&mut probes, &format!("len{}-emoji", n), v);
    }
    push(&mut probes, "len255-all-ff", vec![0xffu8; 255]);
    push(&mut probes, "len256-all-ff", vec![0xffu8; 256]);
    push(&mut probes, "len255-all-caps", vec![b'A'; 255]);
    push(&mut probes, "len256-all-caps", vec![b'A'; 256]);
    push(&mut probes, "len255-all-dots", vec![b'.'; 255]);
    push(&mut probes, "len256-all-dots", vec![b'.'; 256]);
    push(&mut probes, "len255-mixed-hi-caps", {
        let mut v = Vec::new();
        for i in 0..255 {
            v.push(if i % 2 == 0 { b'A' + (i % 26) as u8 } else { 0x80 + (i % 128) as u8 });
        }
        v
    });

    // (O) empty
    push(&mut probes, "empty", Vec::new());

    // (P) every high byte adjacent to every ASCII letter case boundary
    for &hb in &[0x80u8, 0xbf, 0xc0, 0xc3, 0xdf, 0xe0, 0xef, 0xf0, 0xf7, 0xff] {
        for &al in &[b'@', b'A', b'B', b'Y', b'Z', b'[', b'`', b'a', b'z', b'{'] {
            let v = vec![al, hb, al, hb, al];
            push(&mut probes, &format!("adj-{:02x}-{:02x}", hb, al), v);
        }
    }

    // (Q) 3-byte high sequences fully swept over the 3rd byte for one lead pair
    for b3 in [0x80u8, 0x81, 0x9f, 0xa0, 0xbf, 0xc0, 0x41, 0x5a, 0x61, 0x2e, 0x7f] {
        push(&mut probes, &format!("e4b8-{:02x}", b3), vec![0xe4, 0xb8, b3, b'A', b'Z']);
        push(&mut probes, &format!("efbc-{:02x}", b3), vec![0xef, 0xbc, b3, b'A', b'Z']);
    }

    // (R) locale-ish traps: bytes that are uppercase letters in latin1/cp1252
    push(&mut probes, "cp1252-quotes", vec![0x91, 0x92, 0x93, 0x94, 0x96, 0x97]);
    push(&mut probes, "latin1-Y-diaeresis", vec![0x9f, 0xdd, 0xde, 0xdf]);
    push(&mut probes, "latin1-all-C0-DE", (0xc0u8..0xdf).collect::<Vec<u8>>());
    push(&mut probes, "latin1-all-E0-FE", (0xe0u8..0xff).collect::<Vec<u8>>());
    push(&mut probes, "latin1-micro-mu", vec![0xb5, 0xb5]);
    push(&mut probes, "latin1-times-divide", vec![0xd7, 0xf7]);

    // (S) mixed everything torture
    push(&mut probes, "torture1", {
        let mut v = Vec::new();
        v.extend_from_slice(b"XN--");
        v.extend_from_slice(&[0xc0, 0xae]);
        v.extend_from_slice(b"AbC");
        v.push(0x7f);
        v.extend_from_slice(&[0xed, 0xa0, 0x80]);
        v.extend_from_slice(b".TLD");
        v.push(0xff);
        v
    });
    push(&mut probes, "torture2", {
        let mut v = Vec::new();
        for b in (0x01u8..=0xff).rev() {
            v.push(b);
        }
        v.truncate(255);
        v
    });
    push(&mut probes, "torture3", (0x01u8..=0xff).collect::<Vec<u8>>());
    push(&mut probes, "torture4", {
        let mut v: Vec<u8> = Vec::new();
        for b in 0x41u8..=0x5a {
            v.push(b);
            v.push(b | 0x80);
        }
        v
    });
    push(&mut probes, "high-bit-set-caps", (0x41u8..=0x5a).map(|b| b | 0x80).collect::<Vec<u8>>());
    push(&mut probes, "high-bit-set-lower", (0x61u8..=0x7a).map(|b| b | 0x80).collect::<Vec<u8>>());

    // (T) whitespace-ish and dot rules
    push(&mut probes, "space-domain", b"  EXAMPLE . COM  ".to_vec());
    push(&mut probes, "tab-domain", b"\tEXAMPLE\t.\tCOM\t".to_vec());
    push(&mut probes, "double-dot", b"A..B".to_vec());
    push(&mut probes, "hyphen-edges", b"-A-.-B-".to_vec());
    push(&mut probes, "underscore", b"_A_.B".to_vec());

    // ---- execute -------------------------------------------------------
    let mut n_ok = 0usize;
    let mut n_bad = 0usize;
    let total = probes.len();
    for (name, input) in &probes {
        let expected = model(input);
        let actual = run(input);
        if expected == actual {
            n_ok += 1;
        } else {
            n_bad += 1;
            let el = split_lines(&expected);
            let al = split_lines(&actual);
            println!("=== DIVERGENCE [{}] input={} (len {})", name, hexdump(input), input.len());
            let m = el.len().max(al.len());
            for i in 0..m {
                let e = el.get(i).map(|v| hexdump(v)).unwrap_or("<missing>".into());
                let a = al.get(i).map(|v| hexdump(v)).unwrap_or("<missing>".into());
                if e != a {
                    println!("   line {}: model={:?} actual={:?}", i + 1, e, a);
                }
            }
        }
    }
    println!("TOTAL={} OK={} DIVERGENT={}", total, n_ok, n_bad);
}
